   "url": "https://leetcode.com/problems/remove-nth-node-from-end-of-list/",
   "lang": "python",
   "code": "# Definition for singly-linked list.\n# class ListNode:\n# def __init__(self, val=0, next=None):\n# self.val = val\n# self.next = next\nclass Solution:\n    def removeNthFromEnd(self, head: Optional[ListNode], n: int) -> Optional[ListNode]:\n\n        # Initialize fast and slow pointers so when fast reaches the end, slow will be behind it n steps\n        fast = head\n        slow = head\n\n        # Have fast get a lead of n steps from slow\n        for i in range(n):\n        fast = fast.next\n\n        # if fast AKA head is None, then that means there is nothing so return nothing\n        if fast == None:\n        # Returning nothing\n        return head.next\n\n        # Loop until fast reaches the end, then slow will be n steps behind\n        while fast != None:\n\n        # Fast reaches the end\n        if fast.next == None:\n        # Remove the node where slow is by assigning its next to the next nodes' next\n        slow.next = slow.next.next\n\n        # Iterative step\n        slow = slow.next\n        fast = fast.next\n        # At the end, return\n        return head",
   "notes": "",
