   "lang": "python",
   "code": "# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def mergeTwoLists(self, list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]:\n        # Fake starter node so we do not have to handle the first node specially\n        res = ListNode()\n\n        # curr points to the end of the merged list we are building\n        curr = res\n\n        # Keep going while both lists still have nodes\n        while list1 and list2:\n\n            # If list1's current value is smaller, attach list1's node\n            if list1.val < list2.val:\n                curr.next = list1\n                list1 = list1.next\n\n            # Otherwise attach list2's node\n            else:\n                curr.next = list2\n                list2 = list2.next\n\n            # Move curr forward to the node we just attached\n            curr = curr.next\n\n        # If list1 still has leftover nodes, attach all of them\n        if list1:\n            curr.next = list1\n\n        # If list2 still has leftover nodes, attach all of them\n        if list2:\n            curr.next = list2\n\n        # Return the real start of the merged list, skipping the fake node\n        return res.next",
