   "code": "class Solution:\n    def divide(self, dividend: int, divisor: int) -> int:\n        # Initialize the constants for maximum and minimum values\n        INT_MAX = 2**31 - 1\n        INT_MIN = -2**31\n\n        # Initialize quotient\n        quotient = -1\n\n        # Initialize default signs of dividend and divisor\n        dividend_is_neg = False\n        divisor_is_neg = False\n\n        # Check if any negatives\n        if dividend < 0:\n            dividend_is_neg = True\n        if divisor < 0:\n            divisor_is_neg = True\n\n        # Sanitize\n        dividend = abs(dividend)\n        divisor = abs(divisor)\n        # Special overflow case:\n        # -2147483648 / -1 = 2147483648, which is too large\n        if dividend == INT_MIN and divisor == -1:\n            return INT_MAX\n\n        # Operate\n        while dividend >= 0:\n\n            # If dividend is too big, enlarge the divisor\n            temp = divisor\n            multiple = 1\n\n            # Enlarge temp\n            while (temp + temp) <= dividend:\n                temp += temp\n                multiple += multiple\n            dividend -= temp\n            quotient += multiple\n        # If dividend or divisor states are negative, apply to quotient accordingly\n        if divisor_is_neg and dividend_is_neg:\n            quotient = quotient\n        elif divisor_is_neg or dividend_is_neg:\n            quotient = -1*quotient\n\n        # Boundaries\n        if quotient > INT_MAX:\n            return INT_MAX\n\n        if quotient < INT_MIN:\n            return INT_MIN\n        # Return answer\n        return quotient",
