   "lang": "python",
   "code": "# Definition for singly-linked list.\n# class ListNode:\n# def __init__(self, val=0, next=None):\n# self.val = val\n# self.next = next\nclass Solution:\n    def partition(self, head: Optional[ListNode], x: int) -> Optional[ListNode]:\n        result = ListNode(0)\n        tail = result\n\n        curr = head\n        curr2 = head\n\n        # loop thru the list\n        while curr:\n\n        # if node is less than x\n        if curr.val < x:\n\n        # add to result\n        new_node = ListNode(curr.val)\n        tail.next = new_node\n        tail = new_node\n        # advance\n\n        curr = curr.next\n        # after, add the rest:\n        while curr2:\n\n        # if node is less than x\n        if curr2.val >= x:\n\n        # add to result\n        new_node = ListNode(curr2.val)\n        tail.next = new_node\n        tail = new_node\n\n        curr2 = curr2.next\n\n        return result.next",
