   "code": "def isPalindrome(self, s: str) -> bool:\n    alphabet = \"abcdefghijklmnopqrstuvwxyz\"\n    numbers = \"0123456789\"\n\n    lst = []\n    # standardize\n    s_lower = s.lower()\n\n    # Put words in a list\n    for c in s_lower:\n        if c in alphabet or c in numbers:\n            lst.append(c)\n    # Find if palindrome via two pointer method\n    l = 0\n    h = len(lst) - 1\n\n    while l < h:\n        if lst[l] == lst[h]:\n            l += 1\n            h -= 1\n        else:\n            return False\n\n    return True",
