   "difficulty": "Medium",
   "pattern": "Arrays & Hashing",
   "url": "https://leetcode.com/problems/top-k-frequent-elements/",
   "lang": "python",
   "code": "class Solution:\n    def topKFrequent(self, nums: List[int], k: int) -> List[int]:\n        hashmap = {}\n\n        # Find the number of each number in the list\n\n        # Iterate through the length of nums\n        for i in range(len(nums)):\n\n            # if the number is already in hashmap,\n            if nums[i] in hashmap:\n\n                # Increment the times a number is inside a list by 1\n                hashmap[nums[i]] += 1\n            else:\n\n                # Else, just initialize the hashmap to a default value of 1\n                hashmap[nums[i]] = 1\n\n        # Find the top K\n\n        # Initialize a list to store result\n        res = []\n\n        # Iterate through the number of results\n        for i in range(k):\n\n            # Initialize a variable that stores the highest frequency found so far\n            max_count = -1\n            # Initialize a variable that stores which number had that frequency.\n            max_num = None\n\n            # Find highest number\n            for num in hashmap:\n                # If a number of frequencies of each number key of hashmap greater than max_count\n                if hashmap[num] > max_count:\n\n                    # Max count will be the value of frequency\n                    max_count = hashmap[num]\n\n                    # Max num will be the found num\n                    max_num = num\n\n            # Add this to the result\n            res.append(max_num)\n\n            # Delete the key from the hashmap so we dont add it again\n            del hashmap[max_num]\n\n        # Return result\n        return res",
