   "code": "class Solution:\n    def search(self, nums: List[int], target: int) -> int:\n        lo = 0\n        hi = len(nums) - 1\n\n        while lo <= hi:\n            mid = (lo + hi) // 2\n            if nums[mid] < target:\n                lo = mid + 1\n            elif nums[mid] > target:\n                hi = mid - 1\n            else:\n                return mid\n        return -1",
