   "code": "class Solution:\n    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:\n        def higher(currIdx: int, value: int):\n            for i in range(currIdx + 1, len(temperatures)):\n                if temperatures[i] > value:\n                    return (i - currIdx)\n            return 0\n        res = []\n\n        for i in range(len(temperatures)):\n            howManyDays = higher(i, temperatures[i])\n            res.append(howManyDays)\n\n        return res",
